import io
from pptx import Presentation

SRC = r'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
DST = r'C:\Users\HUAWEI\Desktop\_ppt\spot2.txt'
prs = Presentation(SRC)
out = io.open(DST, 'w', encoding='utf-8')
out.write(u'total slides=%d\n' % len(prs.slides))
for idx in (11, 15, 16, 17, 33, 34, 35):
    s = prs.slides[idx]
    note = u''
    try:
        note = s.notes_slide.notes_text_frame.text.strip()[:40]
    except Exception:
        pass
    out.write(u'\n### page %d  note=%r\n' % (idx + 1, note))
    for sh in s.shapes:
        try:
            if sh.has_text_frame and sh.text_frame.text.strip():
                out.write(u'  id=%-4d %s\n' % (sh.shape_id, sh.text_frame.text.replace(u'\n', u' / ')[:130]))
        except Exception:
            pass
        try:
            if sh.has_table:
                t = sh.table
                out.write(u'  TABLE %dx%d rows_h=%s\n' % (len(t.rows), len(t.columns),
                          round(t.rows[0].height / 914400.0, 2)))
                for ri in range(len(t.rows)):
                    cells = [t.cell(ri, ci).text_frame.text for ci in range(len(t.columns))]
                    out.write(u'    %s\n' % u' | '.join(cells))
        except Exception:
            pass
out.close()
