{"content":"import machine
import os
import time
from machine import Pin, SoftSPI

SD_CS, SD_SCK, SD_MOSI, SD_MISO = 14, 21, 47, 4


def levels():
    s = []
    for name, p in (("CS", SD_CS), ("SCK", SD_SCK), ("MOSI", SD_MOSI), ("MISO", SD_MISO)):
        try:
            s.append("%s=%d" % (name, Pin(p, Pin.IN).value()))
        except Exception:
            s.append("%s=ERR" % name)
    print("idle:", " ".join(s))


def cmd0(sck, mosi, miso, hz):
    try:
        spi = SoftSPI(baudrate=hz, polarity=0, phase=0,
                      sck=Pin(sck), mosi=Pin(mosi),
                      miso=Pin(miso, Pin.IN, Pin.PULL_UP))
        cs = Pin(SD_CS, Pin.OUT, value=1)
        cs.value(1)
        spi.write(b"\xff" * 8)
        cs.value(0)
        spi.write(b"\x40\x00\x00\x00\x00\x95")
        r = 0xFF
        for _ in range(8):
            r = spi.read(1, 0xFF)[0]
            if r != 0xFF:
                break
        cs.value(1)
        spi.write(b"\xff")
        try:
            spi.deinit()
        except Exception:
            pass
        return r
    except Exception as e:
        print("   cmd0 err", e)
        return -1


print("=== idle pin levels ===")
levels()

print("=== CMD0 at different clocks ===")
for hz in (400000, 200000, 100000, 50000):
    print("  %6d Hz -> 0x%02X" % (hz, cmd0(SD_SCK, SD_MOSI, SD_MISO, hz)))

print("=== CMD0 with MOSI/MISO swapped ===")
