{"content":"# -*- coding: utf-8 -*-
"""P4X 地面站控制台（一个入口，什么都能干）

用法：
    python p4x.py            # 默认 up：确保 App 在跑；已在跑就重启一次（救黑屏）
    python p4x.py status     # 只看状态，不动
    python p4x.py start      # 只在没跑时启动
    python p4x.py restart    # 强制 kill + 重启（黑屏通常这样能亮）
    python p4x.py web        # 起本地网页服务并打开浏览器

为什么默认要重启：这块板子冷启动后经常"只有背光/全黑"，面板要重新走一遍
上电时序才亮，所以"点一下就能用"= 让 App 重新初始化一次面板。
"""
import io
import os
import re
import subprocess
import sys
import time
import webbrowser

import serial

PORT_HINT = "COM3"
BAUD = 115200
APP = "p4x_gs"
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
LOG = os.path.join(ROOT, "logs", "p4x_ctl.log")
WEB_DIR = os.path.join(ROOT, "web")


def say(msg=""):
    print(msg, flush=True)


def find_port():
    try:
        import serial.tools.list_ports as lp
        ports = list(lp.comports())
        for p in ports:
            if "303A:1001" in (p.hwid or "").upper():
                return p.device
        if ports:
            return ports[0].device
    except Exception:
        pass
    return PORT_HINT


def clean(raw):
    t = raw.decode("utf-8", "replace")
    t = re.sub(r"\x1b\[[0-9;?]*[A-Za-z]", "", t)
    return t.replace("\x00", "")


class Board(object):
    def __init__(self):
        self.port = find_port()
        self.buf = bytearray()
        self.s = serial.Serial(self.port, BAUD, timeout=0.2)
        try:
            self.s.setRTS(False)
            self.s.setDTR(False)
        except Exception:
            pass

    def pump(self, sec):
        t0 = time.time()
        while time.time() - t0 < sec:
            d = self.s.read(8192)
            if d:
                self.buf.extend(d)

    def text(self):
        return clean(self.buf)

    def cmd(self, line, wait=2.5):
        if line:
