"""P4X 答辩稿 · 31 页版（严格对齐官方模板页数/字号，动画交给 PowerPoint 原生接口）"""
import copy
import io
import os
import sys

from pptx import Presentation
from pptx.util import Emu, Pt
from pptx.dml.color import RGBColor
from pptx.enum.shapes import MSO_SHAPE
from pptx.enum.dml import MSO_LINE_DASH_STYLE

SRC = (r'C:\Users\HUAWEI\.dsh\attachments\v1\files\05'
       r'\05ef51df50ac54f2a1efc8e76e0b3e4ef513018e16cc27f7cdcd20c05ed44fa7'
       r'\2026_首届_openvela_AI_硬件全球开发者大赛答辩模板.pptx')
OUT = r'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X_31页.pptx'

R_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
EYEBROW = u'2026 openvela AI 硬件全球开发者大赛 · 答辩'


def shp_by_id(slide, sid):
    for s in slide.shapes:
        if s.shape_id == sid:
            return s
    return None


def _kill_extra(p):
    for r in p.runs[1:]:
        r._r.getparent().remove(r._r)


def set_paras(slide, sid, lines):
    shp = shp_by_id(slide, sid)
    if shp is None:
        return
    if isinstance(lines, str):
        lines = [lines]
    tf = shp.text_frame
    while len(tf.paragraphs) < len(lines):
        last = tf.paragraphs[-1]._p
        last.addnext(copy.deepcopy(last))
    while len(tf.paragraphs) > len(lines):
        p = tf.paragraphs[-1]._p
        p.getparent().remove(p)
    for p, line in zip(tf.paragraphs, lines):
        if p.runs:
            p.runs[0].text = line
            _kill_extra(p)
        else:
            p.add_run().text = line


def set_runs(slide, sid, texts):
    shp = shp_by_id(slide, sid)
    if shp is None:
        return
    p = shp.text_frame.paragraphs[0]
    while len(p.runs) < len(texts):
        p.add_run()
    while len(p.runs) > len(texts):
        p.runs[-1]._r.getparent().remove(p.runs[-1]._r)
    for r, t in zip(p.runs, texts):
        r.text = t


def cell_text(cell, text):
    tf = cell.text_frame
    for p in tf.paragraphs[1:]:
        p._p.getparent().remove(p._p)
    p = tf.paragraphs[0]
    if p.runs:
        p.runs[0].text = text
        _kill_extra(p)
    else:
        p.add_run().text = text


def fill_table(slide, sid, rows):
    shp = shp_by_id(slide, sid)
    if shp is None:
        return
    tbl = shp.table
    while len(tbl.rows) < len(rows):
        tbl._tbl.append(copy.deepcopy(tbl._tbl.tr_lst[-1]))
    while len(tbl.rows) > len(rows):
