{"content":""""交叉验证：这板到底是新板还是老底板？
   —— 把新旧两套引脚都试一遍，看哪套能扫到设备。"""
import machine
import os
import time

print("---- I2C 组合扫描（新旧引脚都试）----")
PAIRS = [("新板 OLED", 48, 42), ("新板 IMU", 40, 38),
         ("老板 MPU", 9, 3), ("老板 BME", 1, 2),
         ("老板 OLED", 12, 11), ("老板 TFT", 12, 11),
         ("IO22/23", 22, 23), ("IO15/16", 15, 16),
         ("IO47/48", 47, 48), ("IO40/41", 40, 41)]
for name, scl, sda in PAIRS:
    try:
        bus = machine.I2C(0, scl=machine.Pin(scl), sda=machine.Pin(sda), freq=100000)
        found = [hex(a) for a in bus.scan()]
        if found:
            print("  %-10s SCL=%-2d SDA=%-2d -> %s   ★有设备"
                  % (name, scl, sda, found))
        else:
            print("  %-10s SCL=%-2d SDA=%-2d -> 空" % (name, scl, sda))
    except Exception as e:
        print("  %-10s ERR %s" % (name, e))

print("---- SD：新板脚 与 老板脚 ----")
COMBOS = [("新板", (7, 5, 6, 11)), ("老板", (14, 21, 47, 4))]
try:
    import sdcard
    for name, (cs, sck, mosi, miso) in COMBOS:
        got = False
        for hz in (200000, 100000):
            try:
                spi = machine.SoftSPI(baudrate=hz, polarity=0, phase=0,
                                      sck=machine.Pin(sck), mosi=machine.Pin(mosi),
                                      miso=machine.Pin(miso, machine.Pin.IN, machine.Pin.PULL_UP))
                sd = sdcard.SDCard(spi, machine.Pin(cs, machine.Pin.OUT), hz)
                try:
                    os.umount("/sd")
                except Exception:
                    pass
                os.mount(sd, "/sd")
                print("  %s CS%d SCK%d MOSI%d MISO%d @%dk OK  %s"
                      % (name, cs, sck, mosi, miso, hz // 1000, os.listdir("/sd")[:4]))
                got = True
                break
            except Exception as e:
                print("  %s CS%d SCK%d MOSI%d MISO%d @%dk : %s"
                      % (name, cs, sck, mosi, miso, hz // 1000, e))
        if got:
            break
except Exception as e:
    print("  sdcard ERR", e)

print("---- RGB 两个脚轮流点（看清楚是哪一个在亮）----")
try:
    import neopixel
    for pin in (47, 48):
        try:
            np = neopixel.NeoPixel(machine.Pin(pin, machine.Pin.OUT), 1)
            for label, c in (("红", (90, 0, 0)), ("绿", (0, 90, 0)), ("蓝", (0, 0, 90))):
                np[0] = c
                np.write()
                print("  GPIO%d -> %s" % (pin, label))
                time.sleep_ms(600)
            np[0] = (0, 0, 0)
            np.write()
        except Exception as e:
            print("  GPIO%d ERR %s" % (pin, e))
except Exception as e:
    print("  neopixel ERR", e)

print("---- LED 指示脚（IO2 / IO48 / IO15）各闪 2 下 ----")
for pin in (2, 48, 15):
    try:
        p = machine.Pin(pin, machine.Pin.OUT)
        for _ in range(2):
            p.value(1)
            time.sleep_ms(200)
            p.value(0)
            time.sleep_ms(200)
        print("  GPIO%-2d 闪过" % pin)
    except Exception as e:
        print("  GPIO%-2d ERR %s" % (pin, e))

print("---- 结束 ----")","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\_hwt_probe2.py"}

