"""抽取会话用户消息（支持 user/message 与 agent/inbox/spliced）。"""
import json
import sys

import zstandard as zstd


def texts_of(content):
    if isinstance(content, str):
        return content
    out = ''
    if isinstance(content, list):
        for c in content:
            if isinstance(c, dict) and c.get('type') == 'text':
                out += c.get('text', '')
    return out


def extract(path):
    d = zstd.ZstdDecompressor().stream_reader(open(path, 'rb')).read().decode('utf-8', 'replace')
    msgs = []
    for line in d.splitlines():
        try:
            o = json.loads(line)
        except Exception:
            continue
        t = o.get('type')
        data = o.get('data') or {}
        if t == 'user/message':
            m = data.get('message') or {}
            txt = texts_of(m.get('content'))
            if txt.strip():
                msgs.append(' '.join(txt.split()))
        elif t == 'agent/inbox/spliced':
            for ins in data.get('inserted') or []:
                if ins.get('role') == 'user':
                    txt = texts_of(ins.get('content'))
                    if txt.strip():
                        msgs.append(' '.join(txt.split()))
    return msgs


if __name__ == '__main__':
    path = sys.argv[1]
    limit = int(sys.argv[2]) if len(sys.argv) > 2 else 15
    ms = extract(path)
    print('用户消息数 =', len(ms))
    for m in ms[:limit]:
        print('  ·', m[:100])","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\extract_user_msgs.py"}

