{"content":"# -*- coding: utf-8 -*-
"""按官方层级表统一字号：
   页面主标题 46 / 章节大标题 72 / 卡片标题 30 / 正文 22 / 注释·页脚 15
   保留：封面主标题 144、章节大数字 120、卡片编号 64（模板设计元素）
"""
import sys

from pptx import Presentation
from pptx.util import Pt

SRC = r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_29页.pptx'
OUT = r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_29页_new.pptx'

KEEP = {46, 72, 64, 120, 144, 96}
MAP = {36: 30, 40: 30, 34: 30, 32: 30, 30: 30, 28: 30, 26: 30,
       24: 22, 23: 22, 21: 22, 19: 22, 18: 15, 17: 15}

prs = Presentation(SRC)
stat = {}

for i, slide in enumerate(prs.slides):
    is_divider = any(
        sh.has_text_frame and any(r.font.size and abs(r.font.size.pt - 72) < 0.01
                                  for p in sh.text_frame.paragraphs for r in p.runs)
        for sh in slide.shapes)
    for sh in slide.shapes:
        if not sh.has_text_frame:
            continue
        txt = sh.text_frame.text.strip()
        if not txt:
            continue
        for p in sh.text_frame.paragraphs:
            for r in p.runs:
                if not r.font.size:
                    continue
                old = round(r.font.size.pt, 1)
                if old in KEEP:
                    continue
                # 章节页的引导语（28pt）按正文 22 处理
                if is_divider and old == 28:
                    new = 22
                else:
                    new = MAP.get(old)
                if new and new != old:
                    r.font.size = Pt(new)
                    stat[(old, new)] = stat.get((old, new), 0) + 1

print('字号调整统计（旧→新 : 处数）:')
for (a, b), n in sorted(stat.items()):
    print('  %5.1f → %5.1f : %d' % (a, b, n))
prs.save(OUT)
print('saved', OUT)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\normalize_fonts.py"}

