{"content":"# -*- coding: utf-8 -*-
"""P11 改为遥测协议页（技术），让技术:应用 ≈ 2:1。"""
import copy

from pptx import Presentation

P = r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_29页.pptx'


def shp(slide, sid):
    for s in slide.shapes:
        if s.shape_id == sid:
            return s
    return None


def paras(slide, sid, texts):
    s = shp(slide, sid)
    if s is None:
        print('  MISS', sid)
        return
    if isinstance(texts, str):
        texts = [texts]
    tf = s.text_frame
    while len(tf.paragraphs) < len(texts):
        tf.paragraphs[-1]._p.addnext(copy.deepcopy(tf.paragraphs[-1]._p))
    while len(tf.paragraphs) > len(texts):
        tf.paragraphs[-1]._p.getparent().remove(tf.paragraphs[-1]._p)
    for p, t in zip(tf.paragraphs, texts):
        if p.runs:
            p.runs[0].text = t
            for r in p.runs[1:]:
                r._r.getparent().remove(r._r)
        else:
            p.add_run().text = t


prs = Presentation(P)
s = prs.slides[10]
paras(s, 3, u'遥测协议：短键 JSON 与带宽预算')
paras(s, 9, u'01 双帧率')
paras(s, 10, [u'快帧 26 B @ 4 Hz：只发姿态，保证跟手。',
              u'全帧 175 B @ 2 Hz：全量字段，够判读。',
              u'合计 455 B/s，链路 960 B/s，余量近半。'])
paras(s, 11, u'02 短键设计')
paras(s, 12, [u'字段名压到 1–2 字符，省约 40% 带宽。',
              u'p 俯仰 / P 气压：大小写严格区分。',
              u'不用二进制：现场要能看包、能改字段。'])
paras(s, 13, u'带宽账可复算：26×4 + 175×2 = 454 B/s；余下的一半留给上行命令与重发。')
prs.save(P)
print('saved in place')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\p11_protocol.py"}

