{"content":"# -*- coding: utf-8 -*-
"""检查每页标题/正文 run 的 latin/ea/cs 与 bold，确认符合官方两档字重。"""
import re
import sys
import zipfile

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_最终_fixed.pptx'

z = zipfile.ZipFile(P)
bad = []
stat = {}
for n in sorted(z.namelist()):
    if not re.match(r'ppt/slides/slide\d+\.xml$', n):
        continue
    x = z.read(n).decode('utf-8', 'replace')
    for m in re.finditer(r'<a:rPr[^>]*?sz="(\d+)"[^>]*?>', x):
        sz = int(m.group(1)) // 100
        seg = x[m.start():m.start() + 500]
        faces = {}
        for tag in ('latin', 'ea', 'cs'):
            mm = re.search(r'<a:%s typeface="([^"]+)"' % tag, seg)
            faces[tag] = mm.group(1) if mm else '-'
        bold = 'b="1"' in m.group(0)
        stat[(sz, tuple(sorted(set(faces.values()))), bold)] = stat.get((sz, tuple(sorted(set(faces.values()))), bold), 0) + 1
        for k, v in faces.items():
            if v not in ('MiSans', '-'):
                bad.append((n, sz, k, v))
z.close()

print('字号 / 字体集合 / 加粗 → 次数')
for (sz, faces, bold), c in sorted(stat.items(), key=lambda x: -x[1])[:10]:
    print('  %4dpt  %-14s bold=%-5s x%d' % (sz, '/'.join(faces), bold, c))
print('\n非 MiSans 的字体:', bad[:6] if bad else '无')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\check_run_fonts.py"}

