{"content":"# -*- coding: utf-8 -*-
"""把 sz=2200 的 rPr 一律设为不加粗（正文 Regular 400）。"""
import re
import sys
import zipfile

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_最终_v2.pptx'

z = zipfile.ZipFile(P)
names = z.namelist()
data = {k: z.read(k) for k in names}
z.close()

n = 0


def fix(m):
    global n
    tag = m.group(0)
    if 'sz="2200"' not in tag:
        return tag
    if 'b="1"' in tag:
        n += 1
        tag = tag.replace('b="1"', 'b="0"')
    return tag


for k, blob in list(data.items()):
    if not k.endswith('.xml'):
        continue
    try:
        s = blob.decode('utf-8')
    except UnicodeDecodeError:
        continue
    s2 = re.sub(r'<a:rPr[^>]*>', fix, s)
    if s2 != s:
        data[k] = s2.encode('utf-8')

out = zipfile.ZipFile(P, 'w', zipfile.ZIP_DEFLATED)
for k in names:
    out.writestr(k, data[k])
out.close()
print('正文去粗:', n)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\deb_22pt.py"}

