"""收尾：把残留的 24pt 归到 22pt，并给缺 ea/cs 的正文补 MiSans。"""
import re
import sys
import zipfile

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT.pptx'

z = zipfile.ZipFile(P)
names = z.namelist()
data = {k: z.read(k) for k in names}
z.close()

n24 = 0
nfix = 0


def fill_missing(m):
    global nfix
    tag = m.group(0)
    if 'sz="2200"' not in tag:
        return tag
    if '<a:ea' in tag:
        return tag
    add = '<a:ea typeface="MiSans" charset="-122"/><a:cs typeface="MiSans" charset="-122"/>'
    nfix += 1
    return tag.replace('</a:rPr>', add + '</a:rPr>')


for k, blob in list(data.items()):
    if not (k.startswith('ppt/slides/') and k.endswith('.xml')):
        continue
    try:
        s = blob.decode('utf-8')
    except UnicodeDecodeError:
        continue
    s2, c = re.subn(r'sz="2400"', 'sz="2200"', s)
    n24 += c
    s2 = re.sub(r'<a:rPr[^>]*>.*?</a:rPr>', fill_missing, s2, flags=re.S)
    if s2 != s:
        data[k] = s2.encode('utf-8')

out = zipfile.ZipFile(P, 'w', zipfile.ZIP_DEFLATED)
for k in names:
    out.writestr(k, data[k])
out.close()
print('24pt -> 22pt :', n24)
