{"content":"# -*- coding: utf-8 -*-
"""正文 22pt 改用 MiSans Normal（400 字重族名；该字体家族里没有 "Regular" 这个名字）。"""
import re
import sys
import zipfile

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT.pptx'

z = zipfile.ZipFile(P)
names = z.namelist()
data = {k: z.read(k) for k in names}
z.close()

n = 0


def fix(m):
    global n
    tag = m.group(0)
    if 'sz="2200"' not in tag:
        return tag
    if 'MiSans Normal' in tag:
        return tag
    # 只替换本标签内的 latin/ea/cs，且必须是 MiSans（不是 MiSans Bold/Light）
    tag2 = re.sub(r'(<a:(?:latin|ea|cs) typeface=")MiSans(")',
                  r'\g<1>MiSans Normal\g<2>', tag)
    if tag2 != tag:
        n += 1
    return tag2


for k, blob in list(data.items()):
    if not (k.startswith('ppt/slides/') and k.endswith('.xml')):
        continue
    try:
        s = blob.decode('utf-8')
    except UnicodeDecodeError:
        continue
    s2 = re.sub(r'<a:rPr[^>]*>.*?</a:rPr>', fix, s, flags=re.S)
    if s2 != s:
        data[k] = s2.encode('utf-8')

out = zipfile.ZipFile(P, 'w', zipfile.ZIP_DEFLATED)
for k in names:
    out.writestr(k, data[k])
out.close()
print('正文 run 改为 MiSans Normal:', n)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\body_to_normal.py"}

