      float y = my[i];
      float z = mz[i];
      float t;

      t = x * cr - z * sr;             /* roll  (about the body axis) */
      z = x * sr + z * cr;
      x = t;

      t = y * cp - z * sp;             /* pitch */
      z = y * sp + z * cp;
      y = t;

      t = x * cyw + z * syw;           /* yaw */
      z = -x * syw + z * cyw;
      x = t;

