{"content":"# -*- coding: utf-8 -*-
"""P4X-ATT8：干净重写姿态定向（替换原 Euler 旋转块）

为什么这么写：
  1) 实测箭体竖直时 accel ≈ +Y（ay≈0.95），而模型机头也是 +Y
     → 模型坐标与传感器坐标一致，**不需要任何安装矩阵**（之前那两版就是乱加矩阵才错）。
  2) 用重力向量定向：把"上"方向 u 旋到世界 +Y，模型自然就"往哪边倒就显示往哪边倒"，
     竖直时也不会退化成"只会绕轴自转"。
  3) 最短弧旋转（Rodrigues）会让左右镜像（已用 tools/verify_orientation.py 验算），
     所以最后把世界 X 取反，正好还原左右；前后不受影响。
  4) roll（绕箭体轴自转）保留在最前，yaw 仍绕世界竖轴。
"""

import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

NEW = '''  /* ---- P4X-ATT8: 用重力向量定向（替掉原来的欧拉角） --------------------
   *
   *   模型机头 = +Y；实测竖直时 accel ≈ +Y  →  安装矩阵是单位阵
   *   u   = normalize(ax, ay, az)      体坐标下的"上"
   *   R   = Rodrigues(u → 世界 +Y)
   *   v'  = Ryaw( R( Ryaw_roll(v) ) )，最后 x = -x 修正最短弧带来的左右镜像
   */

  {
    float ux = fl.ax, uy = fl.ay, uz = fl.az;
    float un = sqrtf(ux * ux + uy * uy + uz * uz);
    int use_gravity = 1;

    if (un > 0.3f && un < 3.0f)
      {
        ux /= un;
        uy /= un;
        uz /= un;
      }
    else
      {
        use_gravity = 0;              /* 失重/异常：退回原来的欧拉角 */
      }

    if (use_gravity)
      {
        /* axis = u × (0,1,0) = (-uz, 0, ux) */
        float kx = -uz;
        float ky = 0.0f;
        float kz = ux;
        float kk = sqrtf(kx * kx + kz * kz);
        float cs = uy;               /* cos(角) = u·(0,1,0) */
        float sn = kk;

        if (kk > 1e-5f)
          {
            kx /= kk;
            kz /= kk;
          }
        else
          {
            kx = 1.0f;
            kz = 0.0f;
            sn = 0.0f;
            cs = (uy >= 0.0f) ? 1.0f : -1.0f;
          }

        for (i = 0; i < nv; i++)
          {
            float x = mx[i];
            float y = my[i];
            float z = mz[i];
            float t;
            float d, cxv, cyv, czv;

            /* 1) roll：绕箭体轴（模型 +Y）自转 */
            t = x * cr - z * sr;
            z = x * sr + z * cr;
            x = t;

            /* 2) Rodrigues：把"上"旋到世界 +Y */
            d = kx * x + ky * y + kz * z;
            cxv = ky * z - kz * y;
            cyv = kz * x - kx * z;
            czv = kx * y - ky * x;

            x = x * cs + cxv * sn + kx * d * (1.0f - cs);
            y = y * cs + cyv * sn + ky * d * (1.0f - cs);
            z = z * cs + czv * sn + kz * d * (1.0f - cs);

            /* 3) yaw：绕世界竖轴 */
            t = x * cyw + z * syw;
            z = -x * syw + z * cyw;
            x = t;

            /* 4) 左右镜像修正（最短弧旋转的方向性） */
            x = -x;

            wx[i] = x;
            wy[i] = y;
            wz[i] = z;
          }
      }
    else
      {
        for (i = 0; i < nv; i++)
          {
            float x = mx[i];
            float y = my[i];
            float z = mz[i];
            float t;

            t = x * cr - z * sr;
            z = x * sr + z * cr;
            x = t;

            t = y * cp - z * sp;
            z = y * sp + z * cp;
            y = t;

            t = x * cyw + z * syw;
            z = -x * syw + z * cyw;
            x = t;

            wx[i] = x;
            wy[i] = y;
            wz[i] = z;
          }
      }
  }

'''

i = s.find('  /* ---- roll about the body axis, then pitch, then yaw')
j = s.find('  /* ---- perspective', i)
if i > 0 and j > i:
    s = s[:i] + NEW + s[j:]
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('ATT8 已写入（替换原 Euler 块）')
else:
    print('MISS 锚点', i, j)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_p4_att8.py"}

{"content":"# -*- coding: utf-8 -*-
"""P4X-ATT9：按"用户定义"的轴来渲染

  俯仰(pitch) = 前后倾  → 绕 X 轴
  滚转(roll)  = 左右倾  → 绕 Z 轴     （原来是绕 Y，所以只会自转）
  偏航(yaw)   = 箭体自转 → 绕 Y 轴    （原来是绕竖轴）

数据侧本来就是这么给的：
  pitch = atan2(ay, az)
  roll  = atan2(-ax, sqrt(ay²+az²))   ← 由 ax 决定，正是"左右倾"
  yaw   = 陀螺 Z 积分                  ← 绕长轴的自转
所以只要把渲染的三次旋转轴换对即可，不需要重力向量。
"""

import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

NEW = '''  /* ---- P4X-ATT9: 三个角按约定各绕自己的轴 -----------------------------
   *
   *   俯仰 pitch → 绕 X 轴（前后倾）
   *   滚转 roll  → 绕 Z 轴（左右倾）
   *   偏航 yaw   → 绕 Y 轴（箭体自转）
   */

  for (i = 0; i < nv; i++)
    {
      float x = mx[i];
      float y = my[i];
      float z = mz[i];
      float t;

      t = x * cr - y * sr;              /* roll：绕 Z 轴 = 左右倾 */
      y = x * sr + y * cr;
      x = t;

      t = y * cp - z * sp;              /* pitch：绕 X 轴 = 前后倾 */
      z = y * sp + z * cp;
      y = t;

      t = x * cyw + z * syw;            /* yaw：绕 Y 轴 = 箭体自转 */
      z = -x * syw + z * cyw;
      x = t;

      wx[i] = x;
      wy[i] = y;
      wz[i] = z;
    }

'''

i = s.find('  /* ---- P4X-ATT8')
j = s.find('  /* ---- perspective', i)
if i > 0 and j > i:
    s = s[:i] + NEW + s[j:]
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('ATT9 已写入（滚转=绕Z，偏航=绕Y）')
else:
    print('MISS 锚点', i, j)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_p4_att9.py"}

