const AI_URL = 'http://127.0.0.1:8766';
const aiHist = [];
let aiBusy = false;

function aiSay(text) {
  $('aiA').textContent = text;
}

async function aiHealth() {
  try {
    const r = await fetch(AI_URL + '/health', { cache: 'no-store' });
    const j = await r.json();
    setDot($('dAi'), j.key ? 'ok' : 'wait', j.key ? '在线 · ' + j.model : '在线(无Key)', $('tAi'));
    return j;
  } catch (e) {
    setDot($('dAi'), 'bad', '未启动', $('tAi'));
    return null;
  }
}

// 从串口日志里挖现场数据，作为 AI 的上下文
function aiContext() {
  const txt = logEl.textContent || '';
  const lines = txt.split('\n').filter(l => l.trim());
  const pick = [];
  const stat = lines.filter(l => /STAT |tx=|lora=|junk=|fix=|sat=|phase=/.test(l)).slice(-6);
  pick.push(...stat);
  pick.push(...lines.slice(-25));
  const board = ['板载任务：' + (lines.some(l => /p4x_gs/.test(l)) ? 'p4x_gs 在跑' : '未见 p4x_gs')];
  return (board.concat(pick)).join('\n').slice(-3500);
}

async function aiAsk(q) {
  q = (q || '').trim();
  if (!q) { aiSay('先写个问题吧。'); return; }
  if (aiBusy) return;
  aiBusy = true;
