  aiSay('思考中…');
  try {
    const body = { q, ctx: aiContext(), history: aiHist.slice(-4) };
    const r = await fetch(AI_URL + '/ask', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const j = await r.json();
    if (j.ok) {
      aiSay(j.answer);
      aiHist.push({ role: 'user', text: q }, { role: 'assistant', text: j.answer });
    } else {
      aiSay('调用失败：' + (j.error || '未知错误') + '\n（确认 网页启动.bat 里的 AI 服务窗口还在）');
