{"content":"# -*- coding: utf-8 -*-
"""P4X-JSONECHO2：改用显式打开 /dev/console 写，绕开 stdout 继承问题。

现象：屏幕上有数据（说明帧收到了、telemetry_apply_json 在跑），
      但 USB 控制台一条 printf 都看不到 —— 这个任务是内核在启动时创建的，
      fd 1 没有指向控制台，printf 静默失败。

做法：每次都 open("/dev/console", O_WRONLY) 再 write()，保证输出能落到控制台。
      4 Hz × 一次 open/close，开销可以忽略。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD_START = '      /* P4X-JSONECHO: 给网页用的回显'
OLD_END = '          }\n      }\n'

i = s.find(OLD_START)
if i < 0:
    print('未找到 JSONECHO 段，可能已改过')
    sys.exit(0)

j = s.find(OLD_END, i)
if j < 0:
    print('未找到段落结尾')
    sys.exit(1)

NEW = '''      /* P4X-JSONECHO2: 直接写 /dev/console（这个任务的 fd 1 不可靠）。
       * 每 2 帧一次（约 4 Hz），格式与网页 dashboard.html 的 parseJSON 对齐。
       */

      {
        static int echo_n;

        if ((++echo_n & 1) == 0)
          {
            int cfd = open("/dev/console", O_WRONLY | O_NONBLOCK);

            if (cfd >= 0)
              {
                char ebuf[240];
                int  elen;

                elen = snprintf(ebuf, sizeof(ebuf),
                                "{\\"alt\\":%.2f,\\"v\\":%.2f,\\"p\\":%.2f,"
                                "\\"r\\":%.2f,\\"y\\":%.2f,\\"ax\\":%.2f,"
                                "\\"ay\\":%.2f,\\"az\\":%.2f,\\"sat\\":%d,"
                                "\\"phase\\":%d,\\"lora\\":1,\\"temp\\":%.1f,"
                                "\\"press\\":%.0f,\\"time\\":\\"%s\\",\\"gps\\":%d}\\n",
                                (double)fl.alt, (double)fl.v, (double)fl.pitch,
                                (double)fl.roll, (double)fl.yaw, (double)fl.ax,
                                (double)fl.ay, (double)fl.az, fl.sat, fl.phase,
                                (double)fl.temperature, (double)fl.pressure,
                                fl.time_str, fl.gps_fix);

                if (elen > 0)
                  {
                    (void)write(cfd, ebuf, (size_t)elen);
                  }

                close(cfd);
              }
          }
      }
'''

s = s[:i] + NEW + s[j + len(OLD_END):]
s = s.replace('P4X-JSONECHO:', 'P4X-JSONECHO2:')
io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
print('已改为 /dev/console 直写')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_jsonecho2.py"}

