{"content":"# -*- coding: utf-8 -*-
"""P4X-JSONECHO3：修掉"帧被截断"——改用阻塞写 + 循环写满。

现象：控制台上出现
    {"alt":0.00,...,"ax":0.00,"ay"{"alt":-0.64,...   ← 上一帧没写完
原因：open(..., O_NONBLOCK) 时 write() 在控制台缓冲满时只写一部分就返回。
做法：去掉 O_NONBLOCK；write() 返回值按已写字节循环，直到整行写完或重试 3 次。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD_OPEN = 'int cfd = open("/dev/console", O_WRONLY | O_NONBLOCK);'
NEW_OPEN = 'int cfd = open("/dev/console", O_WRONLY);'

OLD_WRITE = '''                if (elen > 0)
                  {
                    (void)write(cfd, ebuf, (size_t)elen);
                  }'''
NEW_WRITE = '''                if (elen > 0)
                  {
                    /* 阻塞写 + 循环写满：控制台缓冲小，一次 write 可能只写一部分。 */

                    int sent = 0;
                    int tries = 0;

                    while (sent < elen && tries < 4)
                      {
                        int n = (int)write(cfd, ebuf + sent, (size_t)(elen - sent));

                        if (n > 0)
                          {
                            sent += n;
                          }
                        else
                          {
                            tries++;
                          }
                      }
                  }'''

changed = False
if OLD_OPEN in s:
    s = s.replace(OLD_OPEN, NEW_OPEN, 1)
    changed = True
if OLD_WRITE in s:
    s = s.replace(OLD_WRITE, NEW_WRITE, 1)
    changed = True

if changed:
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('已改为阻塞写 + 写满循环')
else:
    print('未找到目标代码（可能已改过）')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_jsonecho3.py"}

