"""P4X-JSONECHO4：回显绝不允许阻塞 UI（拔掉 USB 线时控制台没有接收方）

现象：拔掉数据线后，背光还亮但画面停住 —— app 卡在 write(/dev/console) 上。
      因为控制台是 USB CDC，线一拔，TX 环形缓冲写满，阻塞写永远不返回，
      UI 线程（就在这个循环里）直接冻死。

做法：用 O_NONBLOCK 打开；有限次重试后**直接丢弃这一帧**。
      宁可丢几帧网页数据，也绝不让屏幕停。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD_OPEN = 'int cfd = open("/dev/console", O_WRONLY);'
NEW_OPEN = 'int cfd = open("/dev/console", O_WRONLY | O_NONBLOCK);'

OLD_WRITE = '''                    int sent = 0;
                    int tries = 0;

                    while (sent < elen && tries < 4)
                      {
                        int n = (int)write(cfd, ebuf + sent, (size_t)(elen - sent));

                        if (n > 0)
                          {
                            sent += n;
                          }
                        else
                          {
                            tries++;
                          }
                      }'''

NEW_WRITE = '''                    /* 非阻塞 + 有限重试：写不进去就丢这一帧。
                     * 拔掉 USB 线后控制台没有接收方，阻塞写会让 UI 永久卡住
                     * （表现为"背光亮着但画面不动"）。
                     */

                    int sent = 0;
                    int tries = 0;

                    while (sent < elen && tries < 3)
                      {
                        int n = (int)write(cfd, ebuf + sent, (size_t)(elen - sent));

                        if (n > 0)
                          {
                            sent += n;
                            tries = 0;
                          }
                        else
                          {
                            tries++;
                          }
                      }'''

changed = False
if OLD_OPEN in s:
    s = s.replace(OLD_OPEN, NEW_OPEN, 1)
    changed = True
if OLD_WRITE in s:
    s = s.replace(OLD_WRITE, NEW_WRITE, 1)
    changed = True

if changed:
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('已改为非阻塞 + 丢弃（不会卡 UI）')
else:
    print('未找到目标代码')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_jsonecho4.py"}

