"""P4X-JSONECHO5：非阻塞 + 带间隔的有限重试（封顶约 40 ms）

echo4 的问题：控制台环形缓冲一次吃不下 150 字节，3 次重试是瞬间完成的，
              全部返回 EAGAIN → 一帧都没写出去。
echo5 的问题回避：每次失败 usleep(2 ms) 再试，最多 20 次（≈40 ms）：
      · 正常插着线：几毫秒就写完，网页照常收数据；
      · 拔掉线：40 ms 后放弃这一帧 —— 最多浪费 4 Hz × 40 ms = 16% 时间，
        UI 依然流畅，绝不会像阻塞写那样永久卡死。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD = '''                    int sent = 0;
                    int tries = 0;

                    while (sent < elen && tries < 3)
                      {
                        int n = (int)write(cfd, ebuf + sent, (size_t)(elen - sent));

                        if (n > 0)
                          {
                            sent += n;
                            tries = 0;
                          }
                        else
                          {
                            tries++;
                          }
                      }'''

NEW = '''                    int sent = 0;
                    int tries = 0;

                    while (sent < elen && tries < 20)
                      {
                        int n = (int)write(cfd, ebuf + sent, (size_t)(elen - sent));

                        if (n > 0)
                          {
                            sent += n;
                            tries = 0;
                          }
                        else
                          {
                            tries++;
                            usleep(2000);      /* 2 ms，给控制台留排空时间 */
                          }
                      }'''

if OLD in s:
    s = s.replace(OLD, NEW, 1)
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('已改为带间隔的有限重试')
else:
    print('未找到写入循环')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_jsonecho5.py"}

