        try:
            s = line.decode("ascii", "ignore").strip()
        except Exception:
            continue
        if not s.startswith("$"):
            continue
        p = s.split(",")
        tag = p[0][3:]
        if tag == "GGA" and len(p) > 9:
            gga.append((p[6], p[7], p[8], p[9]))
        elif tag == "GSV" and len(p) > 7:
            key = p[0][1:3]
            prn = []
            i = 4
            while i + 3 < len(p):
                try:
                    prn.append(int(p[i + 3]))
                except Exception:
                    pass
                i += 4
            gsv.setdefault(key, []).append((p[3], prn))
        elif tag == "RMC" and len(p) > 3:
            rmc.append(p[2])

print("=== 采样 12 秒 ===")
print("GGA 句数:", len(gga), " RMC 句数:", len(rmc))
