if gsv:
    for k, v in gsv.items():
        tot = max((int(x[0]) for x in v), default=0)
        cn0 = [c for _, prns in v for c in prns]
        cn0 = [c for c in cn0 if c > 0]
        print("星座 %s: 视野内 %d 颗, 最强 CN0=%s, 平均 CN0=%.0f, 样本句 %d" %
