{"content":"# -*- coding: utf-8 -*-
"""P4X-P4LAT：让 P4 解析箭载端的短键经纬度，并在回显里带出去

问题：箭载端 full 帧用的是短键 {"la":22.17...,"lo":113.07...}，
      而 P4 的解析代码只找 "lat": / "lon":（长键），所以 fl.lat/fl.lon 永远是 0，
      网页回显里也就没有坐标 → "还没收到火箭坐标"。

改法：
  1) 解析 "la": / "lo":（保留原来长键的兼容）；
  2) JSONECHO 里带上 la/lo。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

# 1) 解析短键 la/lo
OLD_PARSE = '''  {
    const char *p = strstr(line, "\\"lat\\":");
    const char *q = strstr(line, "\\"lon\\":");
    if (p != NULL) fl.lat = strtod(p + 6, NULL);
    if (q != NULL) fl.lon = strtod(q + 6, NULL);
  }'''

NEW_PARSE = '''  {
    const char *p = strstr(line, "\\"lat\\":");
    const char *q = strstr(line, "\\"lon\\":");
    if (p != NULL) fl.lat = strtod(p + 6, NULL);
    if (q != NULL) fl.lon = strtod(q + 6, NULL);

    /* P4X-P4LAT: 箭载端发的是短键 "la" / "lo"，
     * 只找长键会让 fl.lat/fl.lon 永远为 0，网页就说"还没收到火箭坐标"。
     */

    if ((p = strstr(line, "\\"la\\":")) != NULL)
      {
        double v = strtod(p + 5, NULL);
        if (v > -90.0 && v < 90.0)
          {
            fl.lat = v;
            ok++;
          }
      }

    if ((q = strstr(line, "\\"lo\\":")) != NULL)
      {
        double v = strtod(q + 5, NULL);
        if (v > -180.0 && v < 180.0)
          {
            fl.lon = v;
            ok++;
          }
      }
  }'''

if 'P4X-P4LAT' in s:
    print('已打过补丁')
elif OLD_PARSE in s:
    s = s.replace(OLD_PARSE, NEW_PARSE, 1)
    print('已加入 la/lo 解析')
else:
    print('MISS 解析锚点')

# 2) 回显带 la/lo
OLD_ECHO = '''                                "\\"press\\":%.0f,\\"time\\":\\"%s\\",\\"gps\\":%d}\\n",'''
NEW_ECHO = '''                                "\\"press\\":%.0f,\\"la\\":%.7f,\\"lo\\":%.7f,"
                                "\\"time\\":\\"%s\\",\\"gps\\":%d}\\n",'''
if OLD_ECHO in s:
    s = s.replace(OLD_ECHO, NEW_ECHO, 1)
    s = s.replace('(double)fl.pressure,\n                                fl.time_str, fl.gps_fix);',
                  '(double)fl.pressure,\n                                fl.lat, fl.lon,\n                                fl.time_str, fl.gps_fix);', 1)
    print('回显已带 la/lo')
else:
    print('MISS 回显锚点')

io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
print('写入完成')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_p4_latlon.py"}

