{"content":"# -*- coding: utf-8 -*-
"""PPT：拉丁字符改用通用字体，避免在没装 MiSans 的机器上变成乱码符号。

现象：`SoftSPI` 在某台机器/某个预览器里显示成 ⊠⌐§⊠ΨΨ。
原因：这段拉丁文字被设成 MiSans Normal，缺字体时回退到符号字体，
      ASCII 被映射成希腊/数学符号。

做法：保留中文（a:ea）为 MiSans 系列，**只把 a:latin 换成 Arial**。
      Arial 在任何 Windows/Office/WPS 上都有，拉丁字母不会变形。
"""
import sys

from pptx import Presentation

P = r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT.pptx'
LATIN = 'Arial'

prs = Presentation(P)
n = 0
for slide in prs.slides:
    for shape in slide.shapes:
        if not shape.has_text_frame:
            continue
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                rPr = run._r.find(
                    '{http://schemas.openxmlformats.org/drawingml/2006/main}rPr')
                if rPr is None:
                    continue
                latin = rPr.find(
                    '{http://schemas.openxmlformats.org/drawingml/2006/main}latin')
                if latin is not None and (latin.get('typeface') or '').startswith('MiSans'):
                    latin.set('typeface', LATIN)
                    n += 1

prs.save(P)
print('已替换 latin 字体 %d 处' % n)

# 复核
prs = Presentation(P)
bad = 0
for slide in prs.slides:
    for shape in slide.shapes:
        if not shape.has_text_frame:
            continue
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                if run.font.name and run.font.name.startswith('MiSans'):
                    bad += 1
print('仍以 MiSans 作为 latin 的 run:', bad)","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\deck_fix_latin_font.py"}

